structure.mermaidSource:
flowchart TD
  start_integ["Passo 1: Identificação Estrutural da Palavra"] --> dec_autonomia{"O 1º elemento possui autonomia lexical ou é prefixo?"}
  dec_autonomia -- "Prefixo ou Falso Prefixo" --> dec_caso_prefixo{"Qual o caso prefixal aplicável?"}
  dec_autonomia -- "Vocábulo Autônomo" --> dec_elemento_ligacao{"Possui elemento de ligação?"}
  dec_caso_prefixo -- "É co- ou re-" --> res_co_re_2["Aglutina Incondicionalmente (coobrigação, reeditar)"]
  dec_caso_prefixo -- "É prefixo átono" --> res_atono["Aglutina sem Hífen (prerrogativa, predeterminar)"]
  dec_caso_prefixo -- "Inicia por Bem ou Mal" --> dec_bem_mal{"Trata-se de Bem ou Mal?"}
  dec_caso_prefixo -- "Termina em Vogal" --> dec_pref_vogal{"Como inicia o segundo elemento?"}
  dec_caso_prefixo -- "Termina em R (hiper/inter/super)" --> dec_pref_r{"Como inicia o segundo elemento?"}
  dec_bem_mal -- "Palavra com BEM" --> dec_bem_forma{"É aglutinação consagrada no VOLP?"}
  dec_bem_mal -- "Palavra com MAL" --> dec_mal_letra{"Inicia por vogal/H ou por consoante?"}
  dec_bem_forma -- "Sim" --> res_bem_aglut["Aglutinação Consagrada: Ben- (benfazejo, benfeitor)"]
  dec_bem_forma -- "Não" --> res_bem_hifen["Hífen com Bem (bem-estar, bem-vindo)"]
  dec_mal_letra -- "Inicia por Vogal ou H" --> res_mal_hifen["Hífen Obrigatório com Mal (mal-humorado, mal-estar)"]
  dec_mal_letra -- "Inicia por Outra Consoante" --> res_mal_aglut["Aglutina sem Hífen (malcriado, maldito)"]
  dec_pref_vogal -- "Vogais Iguais" --> res_pref_v_igual["Hífen Obrigatório (micro-organismo)"]
  dec_pref_vogal -- "Vogais Diferentes" --> res_pref_v_dif["Junta sem Hífen (autoanálise, infraestrutura)"]
  dec_pref_vogal -- "Inicia por R ou S" --> res_pref_v_rs["Junta e Dobra a Consoante (contrarregra, minissaia)"]
  dec_pref_r -- "Inicia por H ou R" --> res_pref_r_hr["Hífen Obrigatório (super-ricos, super-homem)"]
  dec_pref_r -- "Inicia por S" --> res_pref_r_s["Junta sem Dobrar o S (hipersensibilidade)"]
  dec_pref_r -- "Outras Consoantes ou Vogal" --> res_pref_r_outros["Junta sem Hífen (hipermercado, superpopulação)"]
  dec_elemento_ligacao -- "Sim (Possui Ligação)" --> dec_cat_3b{"É termo botânico/zoológico ou exceção consagrada?"}
  dec_elemento_ligacao -- "Não (Sem Ligação)" --> dec_cat_3a{"Houve perda da noção de composição?"}
  dec_cat_3b -- "Sim (Categoria III-B)" --> res_cat_3b["Hífen Mantido: Exceção Consagrada (cor-de-rosa, cana-de-açúcar)"]
  dec_cat_3b -- "Não (Categoria II Geral)" --> res_cat_2["Sem Hífen: Composto com Ligação (dia a dia, mão de obra)"]
  dec_cat_3a -- "Sim (Categoria III-A)" --> res_cat_3a["Sem Hífen: Perda de Composição (girassol, paraquedas)"]
  dec_cat_3a -- "Não" --> dec_verbo_subst{"A estrutura é Verbo + Substantivo?"}
  dec_verbo_subst -- "Sim (Verbo + Substantivo)" --> res_verbo_subst["Hífen Mantido e R/S Simples (porta-retrato, guarda-roupa)"]
  dec_verbo_subst -- "Não (Outro Composto)" --> res_cat_1["Hífen Obrigatório: Categoria I (decreto-lei, norte-americano)"]

flowchart TD
  start["Início: Análise do Item Cebraspe"] --> dec_tipo_comando{"Qual é o comando ou afirmação do item?"}
  dec_tipo_comando -- "Comando: Mesma Regra" --> proc_comparar["Comparar formação morfológica e regra de cada palavra"]
  proc_comparar --> dec_mesma_regra{"As palavras decorrem da mesma regra do Acordo?"}
  dec_mesma_regra -- "Sim" --> res_certo_regra["Gabarito: CERTO\nMesma fundamentação teórica"]
  dec_mesma_regra -- "Não" --> res_errado_regra["Gabarito: ERRADO\nRegras distintas; hífen comum não basta"]
  dec_tipo_comando -- "Proposta: Grafia Alternativa" --> dec_texto_sem_hifen{"A palavra consta no texto sem hífen (ex: coexistem)?"}
  dec_texto_sem_hifen -- "Sim" --> res_errado_grafia["Gabarito: ERRADO\nCebraspe preserva o padrão do texto-fonte"]
  dec_texto_sem_hifen -- "Não" --> res_analisar_padrao["Avaliar conforme regras gerais do VOLP"]
  dec_tipo_comando -- "Afirmação: Hífen Facultativo" --> dec_facultativo{"Afirma que hífen em adjetivo composto é facultativo?"}
  dec_facultativo -- "Sim" --> res_errado_facultativo["Gabarito: ERRADO\nRegras do Acordo são prescritivas e obrigatórias"]
  dec_facultativo -- "Não" --> res_avaliar_norma["Analisar prescrição normativa aplicável"]
